// Pipeline Register Fields (Read and Write registers)
int IDEX_Rs1, IDEX_Rs2;      // Registers needed by current EX instruction
int EXMEM_Rd, EXMEM_ALUOut;  // Result data one stage back
int MEMWB_Rd, MEMWB_Data;    // Result data two stages back

// Forwarding Logic (Controls EX Stage Input Muxes)
enum FwdSrc { REG_FILE, EX_MEM, MEM_WB };
FwdSrc FWD_A = REG_FILE;

// Check 1: Data available from EX/MEM stage
if (EXMEM_Rd != 0 && IDEX_Rs1 == EXMEM_Rd) {
    FWD_A = EX_MEM;
}
// Check 2: Data available from MEM/WB stage (priority 2)
else if (MEMWB_Rd != 0 && IDEX_Rs1 == MEMWB_Rd) {
    FWD_A = MEM_WB;
}

// Data Selection for ALU Operand A
int OpA = (FWD_A == EX_MEM) ? EXMEM_ALUOut :
          (FWD_A == MEM_WB)  ? MEMWB_Data :
                               IDEX_Rs1_Value;
